     1	package br.com.marealta.report;
     2	
     3	import br.com.marealta.service.ReservationService;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	
     7	/** Único lugar que sabe como um relatório vira CSV: título, cabeçalho, linhas e total. */
     8	public final class CsvWriter {
     9	    public static final String CONTENT_TYPE = "text/csv; charset=utf-8";
    10	
    11	    private CsvWriter() {}
    12	
    13	    public static String render(ReportData report) {
    14	        List<List<String>> lines = new ArrayList<>();
    15	        lines.add(List.of(ReservationService.HOTEL_NAME, report.name(), report.period()));
    16	        lines.add(report.header());
    17	        lines.addAll(report.rows());
    18	        lines.add(report.total());
    19	        StringBuilder sb = new StringBuilder();
    20	        for (List<String> line : lines) {
    21	            sb.append(String.join(",", line.stream().map(CsvWriter::escape).toList())).append('\n');
    22	        }
    23	        return sb.toString();
    24	    }
    25	
    26	    private static String escape(String field) {
    27	        if (field.contains(",") || field.contains("\"") || field.contains("\n") || field.contains("\r")) {
    28	            return '"' + field.replace("\"", "\"\"") + '"';
    29	        }
    30	        return field;
    31	    }
    32	}
