     9	import java.util.function.Function;
    10	import java.util.stream.Collectors;
    11	
    12	public class OccupancyReport implements Report {
    13	    private final Store store;
    14	
    15	    public OccupancyReport(Store store) {
    16	        this.store = store;
    17	    }
    18	
    19	    @Override public String name() { return "occupancy"; }
    20	
    21	    @Override public String parameter() { return "date"; }
    22	
    23	    @Override
    24	    public ReportData generate(String period) {
    25	        LocalDate night = Periods.date(period);
    26	        return store.transaction(tx -> {
    27	            List<Room> rooms = tx.rooms();
    28	            Map<Integer, Room> byNumber = rooms.stream().collect(Collectors.toMap(Room::number, Function.identity()));
    29	            List<Reservation> occupying = tx.occupying(night).stream().filter(r -> r.status().isPaid()).toList();
    30	            List<List<String>> rows = occupying.stream().map(r -> List.of(
    31	                    String.valueOf(r.roomNumber()), byNumber.get(r.roomNumber()).type().name(),
    32	                    String.valueOf(r.id()), r.checkIn().toString(), r.checkOut().toString())).toList();
    33	            long occupied = occupying.stream().map(Reservation::roomNumber).distinct().count();
    34	            return new ReportData(name(), night.toString(),
    35	                    List.of("room", "type", "reservation", "check_in", "check_out"), rows,
    36	                    List.of("total", occupied + "/" + rooms.size()));
    37	        });
    38	    }
