     6	import java.time.format.DateTimeParseException;
     7	import java.util.regex.Pattern;
     8	
     9	public final class Periods {
    10	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    11	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    12	
    13	    private Periods() {}
    14	
    15	    public static LocalDate date(String raw) {
    16	        if (raw != null && DATE.matcher(raw).matches()) {
    17	            try {
    18	                return LocalDate.parse(raw);
    19	            } catch (DateTimeParseException ignored) { }
    20	        }
    21	        throw ApiException.invalid("Data inválida (use aaaa-mm-dd)");
    22	    }
    23	
    24	    public static YearMonth month(String raw) {
    25	        if (raw != null && MONTH.matcher(raw).matches()) {
    26	            try {
    27	                return YearMonth.parse(raw);
    28	            } catch (DateTimeParseException ignored) { }
    29	        }
    30	        throw ApiException.invalid("Mês inválido (use aaaa-mm)");
    31	    }
    32	}
