     9	/** Taxa de turismo da prefeitura: valor por hóspede por noite, vindo da configuração. */
    10	public class TourismTaxReport extends MonthlyReport {
    11	    private final BigDecimal perGuestNight;
    12	
    13	    public TourismTaxReport(Store store, BigDecimal perGuestNight) {
    14	        super(store);
    15	        this.perGuestNight = perGuestNight;
    16	    }
    17	
    18	    @Override public String name() { return "tourism-tax"; }
    19	
    20	    @Override
    21	    protected ReportData build(String period, List<Reservation> startingInMonth) {
    22	        List<Reservation> paid = startingInMonth.stream().filter(r -> r.status().isPaid()).toList();
    23	        BigDecimal sum = Money.ZERO;
    24	        List<List<String>> rows = new java.util.ArrayList<>();
    25	        for (Reservation r : paid) {
    26	            BigDecimal tax = Money.round(perGuestNight.multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    27	            sum = Money.round(sum.add(tax));
    28	            rows.add(List.of(String.valueOf(r.id()), String.valueOf(r.roomNumber()), r.checkIn().toString(),
    29	                    r.checkOut().toString(), String.valueOf(r.guests()), String.valueOf(r.nights()),
    30	                    Money.plain(tax)));
    31	        }
    32	        return new ReportData(name(), period,
    33	                List.of("reservation", "room", "check_in", "check_out", "guests", "nights", "tax"), rows,
