     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Dinheiro: sempre em centavos, arredondamento "meio para o par". */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal value) {
    16	        return value.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static BigDecimal of(String value) {
    20	        return round(new BigDecimal(value));
    21	    }
    22	
    23	    /** Formato dos relatórios CSV e do JSON: 1234.56 */
    24	    public static String plain(BigDecimal value) {
    25	        return round(value).toPlainString();
    26	    }
    27	
    28	    /** Formato dos textos para o hóspede: R$ 1.234,56 */
    29	    public static String brl(BigDecimal value) {
    30	        DecimalFormatSymbols symbols = DecimalFormatSymbols.getInstance(Locale.ROOT);
    31	        symbols.setGroupingSeparator('.');
    32	        symbols.setDecimalSeparator(',');
    33	        DecimalFormat format = new DecimalFormat("#,##0.00", symbols);
    34	        format.setRoundingMode(RoundingMode.HALF_EVEN);
    35	        return "R$ " + format.format(round(value));
    36	    }
    37	}
