     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	/** Regras de preço: alta temporada e plano de tarifa. */
     8	public final class Pricing {
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    11	
    12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    13	
    14	    private Pricing() {}
    15	
    16	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    17	    public static boolean isHighSeason(LocalDate night) {
    18	        Month month = night.getMonth();
    19	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    20	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    21	    }
    22	
    23	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    24	        BigDecimal rate = room.nightlyRate();
    25	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    26	    }
    27	
    28	    /** Pré-condição: checkOut depois de checkIn. */
    29	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    30	        BigDecimal subtotal = Money.ZERO;
    31	        int nights = 0;
    32	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    33	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    34	            nights++;
    35	        }
    36	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    37	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    38	                : Money.ZERO;
    39	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    40	    }
    41	}
