    15	
    16	/** Implementação em memória, usada nos testes. Uma transação por vez. */
    17	public class MemoryStore implements Store, Tx {
    18	    private final Map<Integer, Room> rooms = new TreeMap<>();
    19	    private final Map<Long, Reservation> reservations = new TreeMap<>();
    20	    private final List<Message> messages = new ArrayList<>();
    21	    private long nextReservationId = 1;
    22	    private long nextMessageId = 1;
    23	
    24	    public MemoryStore(List<Room> catalog) {
    25	        catalog.forEach(r -> rooms.put(r.number(), r));
    26	    }
    27	
    28	    @Override
    29	    public synchronized <T> T transaction(Function<Tx, T> work) {
    30	        return work.apply(this);
    31	    }
    32	
    33	    @Override public List<Room> rooms() { return List.copyOf(rooms.values()); }
    34	
    35	    @Override public Optional<Room> room(int number) { return Optional.ofNullable(rooms.get(number)); }
    36	
    37	    @Override public void lockRoom(int number) {}
    38	
    39	    @Override
    40	    public boolean hasActiveOverlap(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    41	        return reservations.values().stream().anyMatch(r -> r.roomNumber() == roomNumber
    42	                && r.status() != ReservationStatus.CANCELLED
    43	                && r.checkIn().isBefore(checkOut) && r.checkOut().isAfter(checkIn));
    44	    }
    45	
    46	    @Override
    47	    public Reservation insert(Reservation draft) {
    48	        Reservation saved = new Reservation(nextReservationId++, draft.roomNumber(), draft.guestName(),
    49	                draft.guestEmail(), draft.guestCpf(), draft.checkIn(), draft.checkOut(), draft.guests(),
    50	                draft.ratePlan(), draft.nights(), draft.subtotal(), draft.discount(), draft.total(),
    51	                draft.status(), draft.amountPaid(), draft.refund());
    52	        reservations.put(saved.id(), saved);
    53	        return saved;
    54	    }
    55	
    56	    @Override public Optional<Reservation> reservationForUpdate(long id) { return reservation(id); }
    57	
    58	    @Override public Optional<Reservation> reservation(long id) { return Optional.ofNullable(reservations.get(id)); }
    59	
    60	    @Override public void update(Reservation reservation) { reservations.put(reservation.id(), reservation); }
    61	
    62	    @Override
    63	    public List<Reservation> startingBetween(LocalDate from, LocalDate to) {
    64	        return reservations.values().stream()
    65	                .filter(r -> !r.checkIn().isBefore(from) && !r.checkIn().isAfter(to))
    66	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
    67	                .toList();
    68	    }
