    71	    public List<Reservation> occupying(LocalDate night) {
    72	        return reservations.values().stream()
    73	                .filter(r -> !r.checkIn().isAfter(night) && r.checkOut().isAfter(night))
    74	                .sorted(Comparator.comparingInt(Reservation::roomNumber).thenComparing(Reservation::id))
    75	                .toList();
    76	    }
