    23	public class PostgresStore implements Store, AutoCloseable {
    24	    private static final String RESERVATION_COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, "
    25	            + "check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, "
    26	            + "amount_paid, refund";
    27	
    28	    private final HikariDataSource dataSource;
    29	
    30	    public PostgresStore(String url, String user, String password, List<Room> catalog) {
    31	        HikariConfig config = new HikariConfig();
    32	        config.setJdbcUrl(url);
    33	        config.setUsername(user);
    34	        config.setPassword(password);
    35	        config.setMaximumPoolSize(10);
    36	        config.setInitializationFailTimeout(60_000); // o banco pode demorar a subir
    37	        this.dataSource = new HikariDataSource(config);
    38	        migrate(catalog);
    39	    }
    40	
    41	    private void migrate(List<Room> catalog) {
    42	        transaction(tx -> {
    43	            Connection c = ((PgTx) tx).connection;
    44	            try (Statement st = c.createStatement()) {
    45	                // evita corrida entre instâncias subindo juntas
    46	                st.execute("SELECT pg_advisory_xact_lock(7070001)");
    47	                st.execute("""
    48	                        CREATE TABLE IF NOT EXISTS rooms (
    49	                            number INTEGER PRIMARY KEY,
    50	                            type VARCHAR(20) NOT NULL,
    51	                            capacity INTEGER NOT NULL,
    52	                            nightly_rate NUMERIC(12,2) NOT NULL)""");
    53	                st.execute("""
    54	                        CREATE TABLE IF NOT EXISTS reservations (
    55	                            id BIGSERIAL PRIMARY KEY,
    56	                            room_number INTEGER NOT NULL REFERENCES rooms(number),
    57	                            guest_name TEXT NOT NULL,
    58	                            guest_email TEXT NOT NULL,
    59	                            guest_cpf TEXT NOT NULL,
    60	                            check_in DATE NOT NULL,
    61	                            check_out DATE NOT NULL,
    62	                            guests INTEGER NOT NULL,
    63	                            rate_plan VARCHAR(20) NOT NULL,
    64	                            nights INTEGER NOT NULL,
    65	                            subtotal NUMERIC(12,2) NOT NULL,
    66	                            discount NUMERIC(12,2) NOT NULL,
    67	                            total NUMERIC(12,2) NOT NULL,
    68	                            status VARCHAR(20) NOT NULL,
    69	                            amount_paid NUMERIC(12,2) NOT NULL,
    70	                            refund NUMERIC(12,2))""");
    71	                st.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations(room_number, check_in)");
    72	                st.execute("CREATE INDEX IF NOT EXISTS reservations_check_in_idx ON reservations(check_in)");
    73	                st.execute("""
    74	                        CREATE TABLE IF NOT EXISTS messages (
    75	                            id BIGSERIAL PRIMARY KEY,
    76	                            channel VARCHAR(20) NOT NULL,
    77	                            recipient TEXT NOT NULL,
    78	                            subject TEXT NOT NULL,
    79	                            body TEXT NOT NULL)""");
    80	            } catch (SQLException e) {
    81	                throw new IllegalStateException(e);
    82	            }
    83	            try (PreparedStatement ps = c.prepareStatement(
    84	                    "INSERT INTO rooms(number, type, capacity, nightly_rate) VALUES (?,?,?,?) "
    85	                            + "ON CONFLICT (number) DO NOTHING")) {
    86	                for (Room r : catalog) {
    87	                    ps.setInt(1, r.number());
    88	                    ps.setString(2, r.type().name());
    89	                    ps.setInt(3, r.capacity());
    90	                    ps.setBigDecimal(4, r.nightlyRate());
    91	                    ps.addBatch();
    92	                }
    93	                ps.executeBatch();
    94	            } catch (SQLException e) {
    95	                throw new IllegalStateException(e);
    96	            }
    97	            return null;
    98	        });
    99	    }
