333	import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
334	
335	/** Mesmos testes contra um PostgreSQL real, num schema descartável. Roda só se DB_URL existir. */
336	@EnabledIfEnvironmentVariable(named = "DB_URL", matches = ".+")
337	class PostgresApiTest extends ApiTestBase {
338	    private PostgresStore store;
339	    private String schema;
340	
341	    @Override
342	    Store newStore() {
343	        String url = System.getenv("DB_URL");
344	        String user = System.getenv("DB_USER");
345	        String password = System.getenv("DB_PASSWORD");
346	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
347	        try (Connection c = DriverManager.getConnection(url, user, password); Statement st = c.createStatement()) {
348	            st.execute("CREATE SCHEMA " + schema);
349	        } catch (Exception e) {
350	            throw new IllegalStateException(e);
351	        }
352	        String scoped = url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema;
353	        store = new PostgresStore(scoped, user, password, Config.ROOMS);
354	        return store;
355	    }
356	
357	    @Override
358	    void closeStore() {
359	        store.close();
360	        try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
361	                System.getenv("DB_PASSWORD")); Statement st = c.createStatement()) {
362	            st.execute("DROP SCHEMA " + schema + " CASCADE");
363	        } catch (Exception e) {
364	            throw new IllegalStateException(e);
365	        }
366	    }
367	}
